try { new Function('X', 'applyMacros', "/* 🎟️ 兑换券：TA 会送你各种券——抱抱券、不许生气券、陪聊到天亮券、任性一次券……想用的时候撕一张，TA 必须兑现。你也能给 TA 写券，TA 会挑个时候来用 */\nif (window.__gyxCoupon) return; window.__gyxCoupon = 1;\nX.feat('gyxCoupon', { n: '🎟️ 兑换券', desc: 'TA 送你各种券，撕一张 TA 就得兑现；你也能给 TA 写券' });\nconst S = X.store('coupon');\nlet D = { list: [] };   // [{id, cid, from:'ta'|'me', name, desc, at, exp, used, said}]\nconst IDEAS = [['抱抱券', '一个很久的抱抱，不许先松手'], ['不许生气券', '不管我做了什么，这次都不许生气'], ['陪聊到天亮券', '今晚聊到你睡着为止'], ['任性一次券', '你说什么就是什么'], ['早安电话券', '明早我打电话叫你起床'], ['夸夸券', '认真夸你十句，不重样'], ['听你吐槽券', '只听，不讲道理'], ['甜品券', '给你买一份你想吃的甜的'], ['撒娇券', '对你撒一次娇，你不许嫌弃'], ['唱歌券', '给你唱一首歌'], ['免罚券', '这次的错可以一笔勾销'], ['陪看电影券', '你选片，我陪着']];\nconst COL = ['#ff8fab', '#ffb86b', '#7bd3b8', '#8fb4ff', '#c79bff', '#ffd36b'];\nconst col = id => COL[[...String(id)].reduce((a, ch) => a + ch.charCodeAt(0), 0) % COL.length];\nasync function give(c, why) {\n    let j = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n你想送她一张「兑换券」${why ? '（' + why + '）' : ''}——她什么时候拿出来用，你都得兑现。\\n已经送过的：${D.list.filter(x => x.cid === String(c.id) && x.from === 'ta').map(x => x.name).join('、') || '（还没有）'}\\n最近的聊天：\\n${X.recent(c, 10)}\\n只输出 JSON：{\"name\":\"券名（2~8 字，以「券」结尾）\",\"desc\":\"能兑换什么（一句话）\",\"say\":\"送券时说的话\"}`));\n    if (!j || !j.name) { const [n, d] = X.pick(IDEAS.filter(x => !D.list.some(y => y.cid === String(c.id) && y.name === x[0] && !y.used)).concat([IDEAS[0]])); j = { name: n, desc: d, say: X.v(`送你一张「${n}」，什么时候用都行。`, `「${n}」一张，收好。`, `这张「${n}」给你，过期不候——骗你的，永久有效。`) }; }\n    const it = { id: 'cp' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4), cid: String(c.id), from: 'ta', name: String(j.name).slice(0, 10), desc: String(j.desc || '').slice(0, 40), at: Date.now(), used: null };\n    D.list.unshift(it); await S.set('d', D); X.say(c, `🎟️ ${X.plain(j.say || '')}`); return it;\n}\nwindow.gyxCouponUse = async id => {\n    const it = D.list.find(x => x.id === id); if (!it || it.used) return; const c = X.char(it.cid); it.used = Date.now(); await S.set('d', D);\n    if (it.from === 'ta') {\n        try { const sid = String(c.id); globalChats[sid] = globalChats[sid] || []; globalChats[sid].push({ sender: 'me', text: `🎟️ 我要用「${it.name}」！`, timestamp: Date.now(), readBy: [], gyx: 1 }); saveAllData(); if (typeof renderChatMessages === 'function' && String(currentChatSessionId) === sid) renderChatMessages(); } catch (e) {}\n        if (X.bailu()) { it.said = X.pick(X.cards(['兑换券', '情话'], c, 2).concat([`好，「${it.name}」收到。${it.desc}——我说到做到。`, `认账认账，「${it.name}」现在兑现。`])); setTimeout(() => X.say(c, it.said), 1500); }\n        else await X.reach(c, `她刚刚撕下了你送她的「${it.name}」（${it.desc}）。你必须兑现：现在就照券上写的做（用文字把兑现的过程做出来），可以假装不情愿但一定要做到`);\n    }\n    window.gyxCouponOpen(it.cid);\n};\nwindow.gyxCouponWrite = async cid => { const n = ((document.getElementById('gyxCoupN') || {}).value || '').trim(), d = ((document.getElementById('gyxCoupD') || {}).value || '').trim(); if (!n) return; D.list.unshift({ id: 'cp' + Date.now().toString(36), cid: String(cid), from: 'me', name: /券$/.test(n) ? n : n + '券', desc: d, at: Date.now(), used: null }); await S.set('d', D); const c = X.char(cid); if (c) X.say(c, X.bailu() ? (X.cards(['情话'], c, 1)[0] || '收到你的券了，我会好好用的。') : (X.plain(await X.ask(`${X.who(c)}\\n她给你写了一张兑换券「${n}」（${d || '没写说明'}），以后你能拿出来用。收到时说一句话。`)) || '收好了，到时候你可别赖账。')); window.gyxCouponOpen(cid); };\nwindow.gyxCouponGive = async cid => { const c = X.char(cid) || X.cur(); await give(c, '她向你讨的'); window.gyxCouponOpen(c.id); };\nwindow.gyxCouponDel = async id => { const x = D.list.find(y => y.id === id); D.list = D.list.filter(y => y.id !== id); await S.set('d', D); window.gyxCouponOpen(x && x.cid); };\nwindow.gyxCouponData = () => D;\nconst ticket = x => `<div class=\"cpn-t${x.used ? ' used' : ''}\" style=\"--c:${col(x.id)}\"><div class=\"cpn-l\"><b>${X.esc(x.name)}</b><span>${X.esc(x.desc || '')}</span><em>${x.from === 'ta' ? 'TA 送你的' : '你写给 TA 的'} · ${new Date(x.at).toLocaleDateString()}${x.used ? ' · 已于 ' + new Date(x.used).toLocaleDateString() + ' 兑换' : ''}</em></div><div class=\"cpn-r\">${x.used ? '已用' : x.from === 'ta' ? `<a onclick=\"gyxCouponUse('${x.id}')\">撕下来用</a>` : '等 TA 用'}<i onclick=\"gyxCouponDel('${x.id}')\">✕</i></div></div>`;\nwindow.gyxCouponOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), L = D.list.filter(x => x.cid === cid);\n    X.panel('gyxCoupOv', '🎟️ 兑换券', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxCouponOpen')}<button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxCouponGive('${cid}')\">跟 TA 讨一张</button></div>\n        <div class=\"cpn-h\">TA 送你的</div>${L.filter(x => x.from === 'ta').map(ticket).join('') || '<div class=\"gyx-tip\">还没有，去讨一张？</div>'}\n        <div class=\"cpn-h\">你写给 TA 的</div>${L.filter(x => x.from === 'me').map(ticket).join('') || '<div class=\"gyx-tip\">还没写过</div>'}\n        <div class=\"gyx-card\"><div class=\"gyx-row\"><input id=\"gyxCoupN\" class=\"gyx-who\" style=\"flex:1\" placeholder=\"券名（陪我打游戏券）\"><input id=\"gyxCoupD\" class=\"gyx-who\" style=\"flex:2\" placeholder=\"能兑换什么\"><button class=\"gyx-btn\" onclick=\"gyxCouponWrite('${cid}')\">写给 TA</button></div></div>`);\n};\nX.ctx(id => { const mine = D.list.filter(x => x.cid === String(id) && x.from === 'me' && !x.used), got = D.list.filter(x => x.cid === String(id) && x.from === 'ta' && !x.used), just = D.list.find(x => x.cid === String(id) && x.used && x.from === 'ta' && Date.now() - x.used < 15 * 60000); if (!mine.length && !got.length && !just) return ''; return `【兑换券】${got.length ? '你送她的、她还没用的：' + got.map(x => x.name).join('、') + '。' : ''}${mine.length ? '她写给你的、你还能用的：' + mine.map(x => `${x.name}（${x.desc}）`).join('、') + '。' : ''}${just ? `她刚用了「${just.name}」（${just.desc}），你得兑现。` : ''}`; }, 'gyxCoupon');\nX.action({ key: 'gyx_coupon', label: '送她一张兑换券', hint: '抱抱券、不许生气券……', need: c => D.list.filter(x => x.cid === String(c.id) && x.from === 'ta' && !x.used).length < 6, run: async c => { const it = await give(c, ''); return it ? '送了一张「' + it.name + '」' : null; } }, 'gyxCoupon');\nX.action({ key: 'gyx_coupon_use', label: '拿出她写给你的券来用', hint: '她写给你的兑换券', need: c => D.list.some(x => x.cid === String(c.id) && x.from === 'me' && !x.used),\n    run: async c => { const it = X.pick(D.list.filter(x => x.cid === String(c.id) && x.from === 'me' && !x.used)); it.used = Date.now(); await S.set('d', D); if (X.bailu()) { X.say(c, `🎟️ 我要用「${it.name}」！`); return '用了一张券'; } return (await X.reach(c, `你拿出她写给你的「${it.name}」（${it.desc}），理直气壮地要她兑现`)) ? '用了一张「' + it.name + '」' : null; } }, 'gyxCoupon');\nX.today(() => ({ title: '🎟️ 兑换券', rows: D.list.filter(x => X.day(new Date(x.used || x.at)) === X.day()).map(x => ({ t: x.used ? '兑换了' : x.from === 'ta' ? '收到' : '写了', x: '「' + X.esc(x.name) + '」', go: `gyxCouponOpen('${x.cid}')` })) }), 'gyxCoupon');\nX.widget('gyxCouponW', { n: '兑换券', sizes: ['s', 'm'], tap: () => window.gyxCouponOpen(), r: w => { const L = D.list.filter(x => x.from === 'ta' && !x.used); return X.gw(w, '🎟️', '兑换券', L.length ? [L.length + ' 张能用', '「' + X.esc(L[0].name) + '」'] : ['讨一张？']); } }, 'gyxCoupon');\nX.memArr({ k: 'gyxCoupon', ico: '🎟️', n: '兑换券', d: '送过、写过、用过的券', arr: () => D.list, text: x => x.name + '：' + (x.desc || ''), edit: (x, v) => { const i = v.indexOf('：'); if (i > 0) { x.name = v.slice(0, i); x.desc = v.slice(i + 1); } else x.name = v; }, meta: x => (x.from === 'ta' ? 'TA 送的' : '你写的') + (x.used ? ' · 已兑换' : ' · 未用'), save: () => S.set('d', D) }, 'gyxCoupon');\nX.css('gyxCoupCss', `.cpn-h{font-weight:700;margin:12px 0 6px}.cpn-t{display:flex;border-radius:14px;overflow:hidden;margin:8px 0;background:var(--c);color:#fff;box-shadow:0 3px 10px rgba(0,0,0,.08)}.cpn-t.used{filter:grayscale(.8);opacity:.6}.cpn-l{flex:1;padding:12px 14px;border-right:2px dashed rgba(255,255,255,.7)}.cpn-l b{font-size:17px;display:block}.cpn-l span{font-size:13px;display:block;opacity:.95}.cpn-l em{font-style:normal;font-size:11px;opacity:.8}.cpn-r{width:84px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-size:13px;position:relative}.cpn-r a{cursor:pointer;background:rgba(255,255,255,.3);padding:4px 8px;border-radius:10px}.cpn-r i{position:absolute;top:4px;right:6px;font-style:normal;font-size:11px;cursor:pointer;opacity:.7}`);\nX.mini({ id: 'gyxCoupon', icon: '🎟️', title: '兑换券', desc: '抱抱券、不许生气券，撕一张 TA 就兑现', cat: '陪伴', onOpen: () => window.gyxCouponOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.list = D.list || []; })();\n\n//# sourceURL=gyx-plugin/兑换券.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎟️ 兑换券 出错：', e); }
/* ==== 🧾 恋爱审批 ==== */
try { new Function('X', 'applyMacros', "/* 🧾 恋爱审批（OA 版）：想熬夜、想喝奶茶、想买那件衣服、想请假晚点回消息？先打报告！填表、选紧急程度、提交给 TA 审批——TA 会通过、驳回或者「附条件通过」，盖章、写批注。TA 也会给你打报告（申请抱抱、申请见面、申请多打一局游戏），你来批 */\nif (window.__gyxOA) return; window.__gyxOA = 1;\nX.feat('gyxOA', { n: '🧾 恋爱审批', desc: 'OA 式打报告：你提申请 TA 审批、TA 提申请你审批，盖章写批注' });\nconst S = X.store('oa');\nlet D = { list: [], seq: 0, cfg: { max: 10 } };   // [{id, no, cid, by:'me'|'ta', type, why, amt, urg, at, due, res:null|'通过'|'驳回'|'附条件通过', note, cond, rat}]\nconst TYPES = [['熬夜申请', '🌙', '时长'], ['奶茶 / 零食申请', '🧋', '数量'], ['购物申请', '🛍️', '金额'], ['请假申请（晚点回消息）', '🏖️', '时长'], ['撒娇申请', '🥺', ''], ['抱抱申请', '🤗', '时长'], ['见面申请', '📍', ''], ['游戏时长申请', '🎮', '时长'], ['免罚申请', '🙏', ''], ['其它申请', '📄', '']];\nconst URG = ['普通', '加急', '特急'];\nconst icoOf = t => (TYPES.find(x => x[0] === t) || [, '📄'])[1];\nconst no = () => { D.seq = (D.seq || 0) + 1; const d = new Date(); return `LOVE-${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}-${String(D.seq).padStart(3, '0')}`; };\nconst stamp = (res, nm) => { const ok = res !== '驳回', col = ok ? '#e0403a' : '#7a7a7a'; return `<svg class=\"oa-stamp\" viewBox=\"0 0 100 100\" width=\"84\" height=\"84\"><circle cx=\"50\" cy=\"50\" r=\"44\" fill=\"none\" stroke=\"${col}\" stroke-width=\"4\"/><circle cx=\"50\" cy=\"50\" r=\"36\" fill=\"none\" stroke=\"${col}\" stroke-width=\"1.5\"/><text x=\"50\" y=\"47\" text-anchor=\"middle\" font-size=\"${res === '附条件通过' ? 12 : 18}\" font-weight=\"700\" fill=\"${col}\">${res === '附条件通过' ? '有条件通过' : res === '通过' ? '同 意' : '驳 回'}</text><text x=\"50\" y=\"66\" text-anchor=\"middle\" font-size=\"9\" fill=\"${col}\">${X.esc(String(nm).slice(0, 6))}</text></svg>`; };\nasync function taDecide(c, x) {\n    const h = new Date().getHours();\n    if (!X.bailu()) { const j = X.json(await X.ask(`${X.who(c)}\\n她给你打了一份报告，请你审批（像领导批 OA，但你是她男朋友）：\\n类型：${x.type}\\n事由：${x.why || '（没写）'}\\n${x.amt ? '数量 / 时长 / 金额：' + x.amt + '\\n' : ''}紧急程度：${x.urg}\\n现在 ${h} 点。\\n按你的性格和对她的关心决定：通过 / 驳回 / 附条件通过（附条件要写清条件）。批注要有你的口吻，20~60 字。\\n只输出 JSON：{\"res\":\"通过 或 驳回 或 附条件通过\",\"note\":\"批注\",\"cond\":\"条件（没有就空）\"}`)); if (j && ['通过', '驳回', '附条件通过'].includes(j.res)) return { res: j.res, note: X.plain(j.note || ''), cond: X.plain(j.cond || '') }; }\n    let res = Math.random() < .6 ? '通过' : Math.random() < .5 ? '附条件通过' : '驳回';\n    if (/撒娇|抱抱|见面/.test(x.type)) res = '通过'; if (/熬夜/.test(x.type) && (h >= 1 && h < 6)) res = '驳回';\n    const cond = res === '附条件通过' ? X.pick(['先喝一杯水', '明天早点睡', '买完给我看看', '少糖少冰', '回来亲我一下', '十二点前必须结束']) : '';\n    const note = X.pick(res === '通过' ? ['准了。下不为例（其实下次也会准）。', '同意，这种报告多打几份。', '批了，玩得开心。'] : res === '驳回' ? ['驳回。太晚了，快去睡觉。', '不批。理由：我心疼。', '驳回，附赠一个抱抱作为补偿。'] : ['可以，但是有条件。', '有条件通过，条件见下。', '原则上同意，细节再议。']);\n    return { res, note, cond };\n}\nasync function decide(x) { const c = X.char(x.cid); if (!c || x.res) return; const r = await taDecide(c, x); Object.assign(x, r, { rat: Date.now() }); await S.set('d', D); X.notify(c, `🧾 ${X.esc(X.name(c))} ${x.res === '驳回' ? X.v('驳回了你的申请', '没批你的报告') : X.v('批了你的申请', '在你的报告上盖了章')}：${X.esc(x.type)}`, x.note, () => window.gyxOAView(x.id)); if (document.getElementById('gyxOAOv')) window.gyxOAOpen(x.cid); }\nasync function tick() { if (!X.on('gyxOA')) return; for (const x of D.list) if (x.by === 'me' && !x.res && x.due <= Date.now()) await decide(x); }\nwindow.gyxOATick = tick;\nwindow.gyxOASubmit = async cid => {\n    const g = id => ((document.getElementById(id) || {}).value || '').trim(); const type = g('gyxOAT') || '其它申请', why = g('gyxOAW'); if (!why) { X.toast('🧾 事由要写', '写清楚才好批'); return null; }\n    const urg = g('gyxOAU') || '普通', mins = urg === '特急' ? 1 : urg === '加急' ? 3 : Math.max(1, +D.cfg.max || 10);\n    const x = { id: 'oa' + Date.now().toString(36), no: no(), cid: String(cid), by: 'me', type, why, amt: g('gyxOAA'), urg, at: Date.now(), due: Date.now() + Math.round(X.rnd(.3, 1) * mins * 60000), res: null };\n    D.list.unshift(x); await S.set('d', D); X.toast('🧾 ' + X.v('报告已提交', '已送审', '流程已发起'), '单号 ' + x.no); window.gyxOAView(x.id); return x;\n};\nwindow.gyxOAUrge = async id => { const x = D.list.find(y => y.id === id); if (!x) return; x.urged = (x.urged || 0) + 1; await decide(x); window.gyxOAView(id); };\nwindow.gyxOAJudge = async (id, res) => {\n    const x = D.list.find(y => y.id === id); if (!x || x.res) return; const c = X.char(x.cid); x.res = res; x.note = ((document.getElementById('gyxOANote') || {}).value || '').trim() || (res === '驳回' ? '驳回。' : '同意。'); x.cond = res === '附条件通过' ? ((document.getElementById('gyxOACond') || {}).value || '').trim() : ''; x.rat = Date.now(); await S.set('d', D);\n    const r = X.bailu() ? X.pick(res === '驳回' ? ['……驳回了？那我再写一份。', '哼，打回来就打回来，我明天还交。', '呜，好吧。'] : ['批了！耶！', '谢谢领导～', '盖章了就不许反悔哦。']) : X.plain(await X.ask(`${X.who(c)}\\n你给她打了「${x.type}」的报告（${x.why}），她${res}了${x.cond ? '，条件：' + x.cond : ''}，批注：「${x.note}」。说一句反应。`) || '收到。');\n    X.say(c, `🧾 ${r}`); window.gyxOAView(id);\n};\nasync function taApply(c) {\n    let j = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n你想给她打一份「恋爱报告」申请点什么（像 OA 审批，正经的格式、撒娇的内容）。\\n可选类型：${TYPES.map(t => t[0]).join('、')}\\n最近的聊天：\\n${X.recent(c, 10)}\\n只输出 JSON：{\"type\":\"类型\",\"why\":\"事由（像写报告一样，30~80 字）\",\"amt\":\"数量 / 时长 / 金额（可空）\",\"urg\":\"普通 或 加急 或 特急\"}`));\n    if (!j || !j.why) { const P = [['抱抱申请', '本人近日思念过度，工作效率下降，特申请抱抱一次，以资鼓励。', '十分钟'], ['见面申请', '经慎重考虑，申请本周末与你见面一次，地点你定，费用我出。', ''], ['游戏时长申请', '申请今晚多打一局游戏，保证打完就睡，绝不拖延。', '一局'], ['撒娇申请', '今日表现良好，特申请撒娇额度一次，望批准。', ''], ['免罚申请', '昨天回消息慢了，申请免罚一次，以后改正。', '']]; const p = X.pick(P); j = { type: p[0], why: p[1], amt: p[2], urg: X.pick(URG) }; }\n    const x = { id: 'oa' + Date.now().toString(36), no: no(), cid: String(c.id), by: 'ta', type: TYPES.some(t => t[0] === j.type) ? j.type : '其它申请', why: X.plain(j.why), amt: X.plain(j.amt || ''), urg: URG.includes(j.urg) ? j.urg : '普通', at: Date.now(), res: null };\n    D.list.unshift(x); await S.set('d', D); return x;\n}\nwindow.gyxOATaApply = async cid => { const c = X.char(cid) || X.cur(); const x = await taApply(c); window.gyxOAView(x.id); return x; };\nwindow.gyxOAData = () => D;\nwindow.gyxOAView = id => {\n    const x = D.list.find(y => y.id === id); if (!x) return; const c = X.char(x.cid), me = X.me(c), ta = X.name(c), from = x.by === 'me' ? me : ta, to = x.by === 'me' ? ta : me;\n    X.panel('gyxOAOv', '🧾 审批单', `<div class=\"oa-form\"><div class=\"oa-hd\"><b>${icoOf(x.type)} ${X.esc(x.type)}</b><span>${x.no}</span></div>\n        <table><tr><th>申请人</th><td>${X.esc(from)}</td><th>审批人</th><td>${X.esc(to)}</td></tr><tr><th>提交时间</th><td colspan=\"3\">${new Date(x.at).toLocaleString()}</td></tr><tr><th>紧急程度</th><td colspan=\"3\"><span class=\"oa-urg u${URG.indexOf(x.urg)}\">${x.urg}</span></td></tr>${x.amt ? `<tr><th>数量/时长/金额</th><td colspan=\"3\">${X.esc(x.amt)}</td></tr>` : ''}<tr><th>事由</th><td colspan=\"3\">${X.esc(x.why)}</td></tr></table>\n        <div class=\"oa-flow\"><span class=\"on\">提交</span><i></i><span class=\"${x.res ? 'on' : 'cur'}\">${X.esc(to)} 审批</span><i></i><span class=\"${x.res ? 'on' : ''}\">归档</span></div>\n        ${x.res ? `<div class=\"oa-res\">${stamp(x.res, to)}<div><b>${x.res}</b>${x.cond ? `<div>条件：${X.esc(x.cond)}</div>` : ''}<div class=\"oa-note gyx-hand\">批注：${X.esc(x.note || '')}</div><em>${new Date(x.rat).toLocaleString()}</em></div></div>`\n        : x.by === 'me' ? `<div class=\"gyx-tip\">审批中……${x.urged ? '（已催办 ' + x.urged + ' 次）' : ''}</div><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;this.textContent='TA 在批…';gyxOAUrge('${x.id}')\">催办</button>`\n        : `<textarea id=\"gyxOANote\" class=\"gyx-in\" rows=\"2\" placeholder=\"批注（可空）\"></textarea><input id=\"gyxOACond\" class=\"gyx-in\" style=\"margin-top:6px\" placeholder=\"附加条件（选「附条件通过」时填）\"><div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxOAJudge('${x.id}','通过')\">同意</button><button class=\"gyx-btn lite\" onclick=\"gyxOAJudge('${x.id}','附条件通过')\">附条件通过</button><button class=\"gyx-btn lite\" onclick=\"gyxOAJudge('${x.id}','驳回')\">驳回</button></div>`}\n        </div><div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxOAOpen('${x.cid}')\">‹ 回列表</button></div>`);\n};\nwindow.gyxOAOpen = function (who, tab) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), L = D.list.filter(x => x.cid === cid), todo = L.filter(x => x.by === 'ta' && !x.res);\n    const row = x => `<div class=\"oa-it\" onclick=\"gyxOAView('${x.id}')\"><span>${icoOf(x.type)}</span><div><b>${X.esc(x.type)}</b><em>${x.no} · ${x.by === 'me' ? '我提交的' : X.esc(X.name(c)) + ' 提交的'}</em></div><i class=\"${x.res === '驳回' ? 'no' : x.res ? 'ok' : 'wait'}\">${x.res || (x.by === 'ta' ? '待我审批' : '审批中')}</i></div>`;\n    X.panel('gyxOAOv', '🧾 恋爱审批', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxOAOpen')}<button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxOATaApply('${cid}')\">让 TA 打份报告</button></div>\n        ${todo.length ? `<div class=\"oa-h\">待我审批（${todo.length}）</div>${todo.map(row).join('')}` : ''}\n        <details class=\"gyx-card\" ${L.length ? '' : 'open'}><summary><b>✍️ 发起申请</b></summary><select id=\"gyxOAT\" class=\"gyx-in\" style=\"margin-top:8px\">${TYPES.map(t => `<option value=\"${t[0]}\">${t[1]} ${t[0]}</option>`).join('')}</select><textarea id=\"gyxOAW\" class=\"gyx-in\" rows=\"3\" style=\"margin-top:6px\" placeholder=\"事由：本人因……特申请……望批准。\"></textarea><div class=\"gyx-row\"><input id=\"gyxOAA\" class=\"gyx-who\" style=\"flex:1\" placeholder=\"数量 / 时长 / 金额（可空）\"><select id=\"gyxOAU\" class=\"gyx-who\">${URG.map(u => `<option>${u}</option>`).join('')}</select></div><div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxOASubmit('${cid}')\">提交审批</button></div><div class=\"gyx-tip\">普通件 TA ${D.cfg.max} 分钟内批，加急 3 分钟，特急 1 分钟；等不及可以「催办」。</div></details>\n        <div class=\"oa-h\">全部（${L.length}）· 通过 ${L.filter(x => x.res && x.res !== '驳回').length} · 驳回 ${L.filter(x => x.res === '驳回').length}</div>${L.filter(x => !(x.by === 'ta' && !x.res)).slice(0, 40).map(row).join('') || '<div class=\"gyx-tip\">还没有报告</div>'}`);\n};\nX.ctx(id => { const L = D.list.filter(x => x.cid === String(id)); if (!L.length) return ''; const wait = L.filter(x => x.by === 'ta' && !x.res), mine = L.filter(x => x.by === 'me' && !x.res), last = L.find(x => x.res && Date.now() - x.rat < 864e5); return `【恋爱审批】${mine.length ? '她提交给你、你还没批的：' + mine.map(x => x.type + '（' + x.why.slice(0, 20) + '）').join('；') + '。' : ''}${wait.length ? '你提交给她、她还没批的：' + wait.map(x => x.type).join('、') + '。' : ''}${last ? `最近一单：${last.by === 'me' ? '她的' : '你的'}「${last.type}」被${last.res}${last.cond ? '（条件：' + last.cond + '）' : ''}。` : ''}`; }, 'gyxOA');\nX.action({ key: 'gyx_oa', label: '给她打一份恋爱报告申请点什么', hint: '恋爱审批', need: c => !D.list.some(x => x.cid === String(c.id) && x.by === 'ta' && !x.res),\n    run: async c => { const x = await taApply(c); X.notify(c, `🧾 ${X.esc(X.name(c))} ${X.v('给你提交了一份申请', '打了份报告等你批', '发起了一个审批流程')}：${X.esc(x.type)}`, x.why, () => window.gyxOAView(x.id)); X.say(c, `🧾 ${X.v('报告已提交，请领导审批。', '我交了一份申请，你快去批～', '流程发起了，等你盖章。')}（${x.type}）`); return '提交了' + x.type; } }, 'gyxOA');\nX.today(() => { const rows = []; D.list.filter(x => x.by === 'ta' && !x.res).forEach(x => rows.push({ t: '待我批', x: icoOf(x.type) + ' ' + X.esc(x.type), go: `gyxOAView('${x.id}')` })); D.list.filter(x => x.res && X.day(new Date(x.rat)) === X.day()).slice(0, 4).forEach(x => rows.push({ t: x.res, x: X.esc(x.type), go: `gyxOAView('${x.id}')` })); return { title: '🧾 恋爱审批', rows }; }, 'gyxOA');\nX.widget('gyxOAW', { n: '恋爱审批', sizes: ['s', 'm'], tap: () => window.gyxOAOpen(), r: w => { const todo = D.list.filter(x => x.by === 'ta' && !x.res), wait = D.list.filter(x => x.by === 'me' && !x.res); return X.gw(w, '🧾', '恋爱审批', [todo.length ? todo.length + ' 份待我批' : wait.length ? wait.length + ' 份审批中' : '打份报告？', D.list[0] ? X.esc(D.list[0].type) + (D.list[0].res ? ' · ' + D.list[0].res : '') : '']); } }, 'gyxOA');\nX.memArr({ k: 'gyxOA', ico: '🧾', n: '恋爱审批', d: '打过的报告和批注', arr: () => D.list, text: x => x.type + '：' + x.why + (x.res ? '｜' + x.res + '：' + (x.note || '') : ''), edit: (x, v) => { const m = v.match(/^(.*?)：(.*?)(?:｜(.*?)：(.*))?$/); if (m) { x.why = m[2]; if (m[4] != null) x.note = m[4]; } }, meta: x => x.no + ' · ' + (x.by === 'me' ? '我提交' : 'TA 提交'), save: () => S.set('d', D) }, 'gyxOA');\nX.css('gyxOACss', `.oa-form{border:1px solid #e3e6ea;border-radius:14px;padding:12px;background:#fbfcfd;font-size:13.5px}.oa-hd{display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid #2f6fde;padding-bottom:6px;margin-bottom:8px}.oa-hd b{font-size:16px;color:#2f6fde}.oa-hd span{font-family:monospace;font-size:11.5px;color:#888}.oa-form table{width:100%;border-collapse:collapse}.oa-form th,.oa-form td{border:1px solid #e3e6ea;padding:6px 8px;text-align:left;vertical-align:top}.oa-form th{background:#f2f5f9;color:#666;font-weight:500;width:84px;white-space:nowrap}.oa-urg{padding:1px 8px;border-radius:8px;font-size:12px}.oa-urg.u0{background:#eef2f7}.oa-urg.u1{background:#fff1d6;color:#b26b00}.oa-urg.u2{background:#ffe0e0;color:#c62828}.oa-flow{display:flex;align-items:center;gap:6px;margin:12px 0;font-size:12px}.oa-flow span{padding:3px 10px;border-radius:10px;background:#eee;color:#999}.oa-flow span.on{background:#2f6fde;color:#fff}.oa-flow span.cur{background:#fff1d6;color:#b26b00}.oa-flow i{flex:1;height:2px;background:#ddd}.oa-res{display:flex;gap:12px;align-items:center}.oa-res b{font-size:16px}.oa-note{font-size:17px;margin:4px 0;color:#c0392b}.oa-res em{font-style:normal;font-size:11px;color:#aaa}.oa-stamp{transform:rotate(-14deg);flex:none}.oa-h{font-weight:700;margin:12px 0 4px}.oa-it{display:flex;gap:10px;align-items:center;padding:9px 4px;border-bottom:1px solid #f2f2f4;cursor:pointer}.oa-it>span{font-size:22px}.oa-it>div{flex:1}.oa-it em{display:block;font-style:normal;font-size:11px;color:#999;font-family:monospace}.oa-it>i{font-style:normal;font-size:12px;padding:2px 8px;border-radius:8px}.oa-it>i.ok{background:#e6f7ec;color:#1e8e3e}.oa-it>i.no{background:#f2f2f2;color:#888}.oa-it>i.wait{background:#fff1d6;color:#b26b00}`);\nX.mini({ id: 'gyxOA', icon: '🧾', title: '恋爱审批', desc: 'OA 式打报告，互相审批盖章', cat: '一起做', onOpen: () => window.gyxOAOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.list = D.list || []; D.cfg = Object.assign({ max: 10 }, D.cfg || {}); setTimeout(tick, 15000); setInterval(tick, 30000); })();\n\n//# sourceURL=gyx-plugin/恋爱审批.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🧾 恋爱审批 出错：', e); }
/* ==== 🎁 愿望清单 ==== */
try { new Function('X', 'applyMacros', "/* 🎁 愿望清单：你写下想要的东西，TA 会偷偷记着，哪天悄悄帮你实现一个（礼物盒寄到）；TA 也有自己的愿望清单，你能送 TA 礼物 */\nif (window.__gyxWish) return; window.__gyxWish = 1;\nX.feat('gyxWish', { n: '🎁 愿望清单', desc: '互相的愿望清单，TA 会偷偷帮你实现一个' });\nconst S = X.store('wish');\nlet D = { mine: [], ta: {}, cfg: { per: 6 } };   // mine:{id,t,note,done,by,at,msg}; ta[cid]=[{id,t,why,done,at}]\nasync function taWishes(c) {\n    if (X.bailu()) return ['一起去看一次海', '一台新耳机', '你亲手写的信', '一只毛绒熊', '周末一起睡懒觉'].map(t => ({ t, why: '' }));\n    const j = X.json(await X.ask(`${X.who(c)}\\n写下你自己的愿望清单（5 条，符合你的身份性格：有想要的东西，也有想和她一起做的事，具体一点）。\\n只输出 JSON：{\"list\":[{\"t\":\"愿望\",\"why\":\"为什么想要（一句）\"}]}`));\n    return (j && Array.isArray(j.list) ? j.list : []).slice(0, 8).map(x => ({ t: String(x.t || ''), why: String(x.why || '') })).filter(x => x.t);\n}\n// TA 偷偷帮你实现一个\nasync function fulfill(c, w) {\n    w = w || X.pick(D.mine.filter(x => !x.done)); if (!c || !w) return null;\n    let msg;\n    if (X.bailu()) msg = X.cards(['礼物', '信', '聊天'], c, 2).join('\\n') || '你说过想要这个，我记着呢。';\n    else msg = X.plain(await X.ask(`${X.who(c)}\\n她的愿望清单里写着「${w.t}」${w.note ? '（' + w.note + '）' : ''}。你偷偷帮她实现了（买了 / 安排好了 / 做到了），附一张小卡片。写卡片上的话（40~120 字）。只输出卡片内容。`) || '你说过想要的，我一直记着。');\n    w.done = true; w.by = String(c.id); w.at = Date.now(); w.msg = msg; w.unopened = true; await S.set('d', D);\n    X.notify(c, `🎁 ${X.name(c)} 偷偷实现了你的一个愿望`, '去拆开', 'gyxWishOpen');\n    await X.reach(c, `你刚偷偷帮她实现了愿望清单里的「${w.t}」，礼物已经到她那儿了，神秘一点地告诉她去拆`);\n    return w;\n}\nwindow.gyxWishFulfill = (id, wid) => fulfill(X.char(id) || X.cur(), D.mine.find(x => x.id === wid));\nwindow.gyxWishOpen = async function (tab, who) {\n    const T = tab || window.__gyxWsTab || 'mine'; window.__gyxWsTab = T;\n    const c = X.char(who) || X.cur(), cid = c ? String(c.id) : '';\n    let body = '';\n    if (T === 'mine') body = `<div class=\"gyx-row\"><input id=\"gyxWsT\" class=\"gyx-in\" placeholder=\"想要的东西 / 想做的事\" style=\"flex:2\"><input id=\"gyxWsN\" class=\"gyx-in\" placeholder=\"备注（可空：颜色、链接……）\" style=\"flex:1\"><button class=\"gyx-btn\" onclick=\"gyxWishAdd()\">写下</button></div>\n        <div class=\"gyx-tip\">你的愿望，TA 都看得到，会偷偷记着。</div>\n        ${D.mine.map(w => `<div class=\"ws-it${w.done ? ' done' : ''}\">${w.done ? (w.unopened ? `<b class=\"ws-new\" onclick=\"gyxWishUnbox('${w.id}')\">🎁 拆开</b>` : '✅') : '⭐'}<div><b>${X.esc(w.t)}</b>${w.note ? `<span>${X.esc(w.note)}</span>` : ''}${w.done && !w.unopened ? `<span>${X.esc(X.name(X.char(w.by)))} 帮你实现了 · ${new Date(w.at).toLocaleDateString()}</span><p class=\"gyx-hand\">${X.esc(w.msg || '')}</p>` : ''}</div>${w.done ? '' : `<i onclick=\"gyxWishDel('${w.id}')\">×</i>`}</div>`).join('') || '<div class=\"gyx-tip\">还没写愿望。</div>'}`;\n    else { if (c && !D.ta[cid]) { body = '<div class=\"gyx-tip\">TA 在想自己想要什么……</div>'; setTimeout(async () => { D.ta[cid] = (await taWishes(c)).map((x, i) => Object.assign({ id: 'tw' + Date.now() + i, done: false }, x)); await S.set('d', D); window.gyxWishOpen('ta', cid); }, 10); }\n        else body = `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxWishTaWho')}</div>${(D.ta[cid] || []).map(w => `<div class=\"ws-it${w.done ? ' done' : ''}\">${w.done ? '✅' : '💭'}<div><b>${X.esc(w.t)}</b>${w.why ? `<span>${X.esc(w.why)}</span>` : ''}${w.done ? `<span>你送给 TA 了 · ${new Date(w.at).toLocaleDateString()}</span>` : ''}</div>${w.done ? '' : `<button class=\"gyx-btn lite\" onclick=\"gyxWishGive('${cid}','${w.id}')\">送给 TA</button>`}</div>`).join('')}<div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"GYX_WISH_RESET('${cid}')\">让 TA 重新写</button></div>`; }\n    X.panel('gyxWsOv', '🎁 愿望清单', `<div class=\"gyx-row\"><span class=\"gyx-chip ${T === 'mine' ? 'on' : ''}\" onclick=\"gyxWishOpen('mine')\">我的愿望</span><span class=\"gyx-chip ${T === 'ta' ? 'on' : ''}\" onclick=\"gyxWishOpen('ta')\">TA 的愿望</span></div>${body}\n        <div class=\"gyx-row gyx-tip\">默认模式的 TA 每天有 <input class=\"gyx-who\" type=\"number\" min=\"0\" max=\"100\" value=\"${D.cfg.per}\" style=\"width:60px\" onchange=\"gyxWishCfg(+this.value)\">% 的可能偷偷实现你一个愿望；自主模式的 TA 自己决定。</div>`);\n};\nwindow.gyxWishTaWho = v => window.gyxWishOpen('ta', v);\nwindow.GYX_WISH_RESET = async cid => { delete D.ta[cid]; await S.set('d', D); window.gyxWishOpen('ta', cid); };\nwindow.gyxWishAdd = async () => { const t = ((document.getElementById('gyxWsT') || {}).value || '').trim(); if (!t) return; D.mine.unshift({ id: 'w' + Date.now(), t, note: ((document.getElementById('gyxWsN') || {}).value || '').trim(), done: false }); await S.set('d', D); window.gyxWishOpen('mine'); };\nwindow.gyxWishDel = async id => { D.mine = D.mine.filter(x => x.id !== id); await S.set('d', D); window.gyxWishOpen('mine'); };\nwindow.gyxWishGive = async (cid, id) => { const w = (D.ta[cid] || []).find(x => x.id === id); if (!w) return; w.done = true; w.at = Date.now(); await S.set('d', D); X.reach(X.char(cid), `她送了你一直想要的「${w.t}」，你收到了！按你的性格反应（惊喜、感动、嘴硬……）`); X.toast(X.v('送出去了', '礼物在路上了'), w.t); window.gyxWishOpen('ta', cid); };\nwindow.gyxWishUnbox = async id => { const w = D.mine.find(x => x.id === id); if (!w) return; w.unopened = false; await S.set('d', D); const ov = document.createElement('div'); ov.className = 'ws-box'; ov.onclick = () => { ov.remove(); window.gyxWishOpen('mine'); }; ov.innerHTML = `<div class=\"ws-card\"><div class=\"ws-e\">🎁</div><b>${X.esc(w.t)}</b><p class=\"gyx-hand\">${X.esc(w.msg || '')}</p><small>—— ${X.esc(X.name(X.char(w.by)))}</small></div>`; document.body.appendChild(ov); };\nwindow.gyxWishCfg = v => { D.cfg.per = v; S.set('d', D); };\nwindow.gyxWishData = () => D;\nasync function tick() { if (!X.on('gyxWish')) return; const k = X.day(); if (D.last === k) return; D.last = k; await S.set('d', D); if (!D.mine.some(x => !x.done)) return; for (const c of X.chars()) { if (X.auto(c)) continue; if (Math.random() * 100 < (+D.cfg.per || 0)) { await fulfill(c); break; } } }\nX.action({ key: 'gyx_wish', label: '偷偷实现她愿望清单里的一个愿望', hint: '她写过想要的东西', need: () => D.mine.some(x => !x.done), run: async c => (await fulfill(c)) ? '偷偷实现了你一个愿望' : null }, 'gyxWish');\nX.ctx(id => { const L = D.mine.filter(x => !x.done).slice(0, 8); const T = (D.ta[String(id)] || []).filter(x => !x.done).slice(0, 5); let t = ''; if (L.length) t += `【她的愿望清单】${L.map(x => x.t).join('、')}（你知道，可以放在心上）。`; if (T.length) t += `【你自己的愿望清单】${T.map(x => x.t).join('、')}。`; return t; }, 'gyxWish');\nX.today(() => ({ title: '🎁 愿望', rows: D.mine.filter(w => w.unopened).map(w => ({ t: '🎁', x: `<b>「${X.esc(w.t)}」实现了，去拆开</b>`, go: `gyxWishUnbox('${w.id}')` })) }), 'gyxWish');\nX.css('gyxWsCss', `.ws-it{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border-radius:14px;background:#f7f7f9;margin:6px 0}.ws-it.done{background:#fff7e6}.ws-it>div{flex:1}.ws-it b{display:block;font-weight:500}.ws-it span{display:block;font-size:12px;color:#999}.ws-it p{font-size:17px;margin:6px 0 0}.ws-it i{font-style:normal;color:#ccc;cursor:pointer}.ws-new{color:#e07a00;cursor:pointer;white-space:nowrap;animation:gbWig 1.4s infinite}\n.ws-box{position:fixed;inset:0;z-index:100006;background:rgba(40,20,30,.6);display:flex;align-items:center;justify-content:center}.ws-card{background:#fffdf6;border-radius:20px;padding:26px 24px;width:min(360px,86vw);text-align:center;animation:giPop .6s cubic-bezier(.3,1.5,.5,1) both}.ws-e{font-size:60px}.ws-card b{font-size:20px}.ws-card p{font-size:19px;line-height:1.8;text-align:left}.ws-card small{color:#999}\n@keyframes giPop{from{opacity:0;transform:scale(.5)}to{opacity:1;transform:none}}@keyframes gbWig{0%,100%{transform:rotate(0)}5%{transform:rotate(-4deg)}10%{transform:rotate(4deg)}15%{transform:rotate(0)}}`);\nX.mini({ id: 'gyxWish', icon: '🎁', title: '愿望清单', desc: '你写下想要的，TA 会偷偷帮你实现；TA 也有愿望清单，你能送 TA 礼物', onOpen: () => window.gyxWishOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.mine = D.mine || []; D.ta = D.ta || {}; D.cfg = Object.assign({ per: 6 }, D.cfg || {}); setTimeout(tick, 30000); setInterval(tick, 30 * 60000); })();\nX.widget('gyxWishW', { n: '愿望清单', sizes: ['s', 'm'], tap: () => window.gyxWishOpen(), r: w => { const u = D.mine.filter(x => x.unopened), left = D.mine.filter(x => !x.done); return X.gw(w, '🌠', '愿望清单', [u.length ? '<b>🎁 实现了，去拆</b>' : left.length + ' 个愿望', left[0] ? X.esc(left[0].t) : '写一个愿望', D.mine.filter(x => x.done).length + ' 个实现了']); } }, 'gyxWish');\nX.mem({ k: 'gyxWish', ico: '🌠', n: '愿望清单', d: '你的愿望（TA 知道）和 TA 的愿望', items: c => D.mine.concat(D.ta[String(c.id)] || []), text: x => x.t, meta: x => (D.mine.includes(x) ? '你的' : 'TA 的') + (x.done ? ' · 实现了' : ''), edit: (x, v) => { x.t = v; }, del: (c, i) => { const all = D.mine.concat(D.ta[String(c.id)] || []), x = all[i]; let j = D.mine.indexOf(x); if (j >= 0) D.mine.splice(j, 1); else { const L = D.ta[String(c.id)] || []; j = L.indexOf(x); if (j >= 0) L.splice(j, 1); } }, save: () => S.set('d', D) }, 'gyxWish');\n\n//# sourceURL=gyx-plugin/愿望清单.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎁 愿望清单 出错：', e); }
